from django.utils.text import slugify


def populate_slugs_and_mptt(apps, schema_editor):
    Category = apps.get_model('catalog', 'Category')
    Course = apps.get_model('catalog', 'Course')

    for cat in Category.objects.all():
        if not cat.slug:
            base_slug = slugify(cat.name) or "kategoria"
            slug = base_slug
            counter = 1
            while Category.objects.filter(slug=slug).exclude(pk=cat.pk).exists():
                slug = f"{base_slug}-{counter}"
                counter += 1
            cat.slug = slug
            cat.save(update_fields=['slug'])

    for course in Course.objects.all():
        if not course.slug:
            base_slug = slugify(course.title) or "kurs"
            slug = base_slug
            counter = 1
            while Course.objects.filter(slug=slug).exclude(pk=course.pk).exists():
                slug = f"{base_slug}-{counter}"
                counter += 1
            course.slug = slug
            course.save(update_fields=['slug'])


